import math

def degree_to_radian(degrees: float) -> float:
    """Convert an angle from degrees to radians."""
    return degrees * (math.pi / 180.0)


# Example usage and assertion check
if __name__ == "__main__":
    assert abs(degree_to_radian(90) - math.radians(90)) < 1e-15, "Conversion failed!"
    print(f"degree_to_radian(90) = {degree_to_radian(90)}")

